let day = $json.Day;
let postNumber = $json.Post_Number;

// 🔥 FORCE STRING SAFETY
if (typeof day !== "string") {
  day = JSON.stringify(day || "day");
}

if (typeof postNumber !== "string") {
  postNumber = String(postNumber || "post");
}

// clean values
postNumber = postNumber.replace(/\s+/g, "-");

const cleanDay = day
  .replace(/[^a-zA-Z0-9]/g, "-")
  .replace(/^-|-$/g, "");

// fallback safety (important)
const safeDay = cleanDay || "day";
const safePost = postNumber || "post";

const fileName = `${safeDay}-${safePost}.jpg`;

return {
  ...$json,
  Image_URL: `https://YOUR_PROJECT.supabase.co/storage/v1/object/public/aquaponics-media/${fileName}`
};

// 1. Get inputs from the Form Trigger
const topic = $input.item.json.topic;
const startDateStr = $input.item.json.startDate;
const endDateStr = $input.item.json.endDate;

// 2. Convert strings into real Date objects
const start = new Date(startDateStr);
const end = new Date(endDateStr);

// 3. Calculate the duration (number of days) for Gemini's reference
const diffTime = Math.abs(end - start);
const duration = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1; // +1 to include both start and end days

// 4. Return everything to the next node
return {
  topic: topic,
  startDate: start.toISOString(),
  endDate: end.toISOString(),
  duration: duration
};

let rawText;

try {
  rawText =
    $node["Message a model"].json.content?.parts?.[0]?.text ||
    $node["Message a model"].json.candidates?.[0]?.content?.parts?.[0]?.text ||
    $node["Message a model"].json.text ||
    "";
} catch (e) {
  throw new Error("AI response missing");
}

if (!rawText) {
  throw new Error(
    "AI response text missing. Full response:\n" +
    JSON.stringify($node["Message a model"].json, null, 2)
  );
}

rawText = String(rawText)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const jsonMatch = rawText.match(/\[[\s\S]*\]/);

if (!jsonMatch) {
  throw new Error("No JSON array found in AI response:\n" + rawText);
}

let campaignData;

try {
  campaignData = JSON.parse(jsonMatch[0]);
} catch (e) {
  throw new Error("Invalid JSON:\n" + rawText);
}

if (!Array.isArray(campaignData)) {
  campaignData = [campaignData];
}

const angleRotation = ["Offer", "Benefit", "Freshness", "Sustainability", "Education", "Trust", "Urgency"];

const creativeDirections = [
  "editorial premium",
  "cinematic lifestyle",
  "modern DTC",
  "organic luxury",
  "energetic commercial",
  "documentary realism"
];

const adFocuses = [
  "product-focused",
  "produce-focused",
  "system-focused",
  "lifestyle-focused",
  "educational-focused",
  "sustainability-focused",
  "mascot-focused"
];

const mascotActions = [
  "pointing",
  "holding produce",
  "explaining",
  "interacting with plants",
  "presenting product",
  "harvesting",
  "celebrating freshness"
];

const compositionDirections = [
  "premium product hero shot with soft Indian balcony background",
  "cinematic product close-up with negative space on the left",
  "product displayed beside fresh greens in Indian terrace light",
  "editorial kitchen scene with product and herbs",
  "clean product-first commercial composition",
  "lifestyle scene with family harvesting from home system",
  "wide terrace farming scene with clean wall space for text"
];

const flattenedRows = [];

campaignData.forEach((dayEntry, dayIndex) => {
  const dayValue = dayEntry.day || `Day ${dayIndex + 1}`;

  const postList = Array.isArray(dayEntry.posts)
    ? dayEntry.posts
    : [dayEntry];

  postList.forEach((post, index) => {
    const cleanDay = String(dayValue)
      .replace(/[^a-zA-Z0-9]/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "");

    const rowId = `${cleanDay}-${index + 1}`;

    let postType = String(post.post_type || "").toLowerCase();
    postType = postType.includes("reel") ? "Reel" : "Post";

    const adCopy = post.ad_copy || {};

    const headline = postType === "Post"
      ? String(adCopy.headline || "Fresh. Clean. Local.").trim()
      : "";



    const cta = postType === "Post"
      ? String(adCopy.cta || "Shop Now").trim()
      : "";

    const features = Array.isArray(adCopy.features)
      ? adCopy.features.map(f => String(f).trim()).filter(Boolean)
      : ["Chemical-free", "Fresh harvest", "Sustainable"];

    const marketingAngle = postType === "Post"
      ? String(post.marketing_angle || angleRotation[dayIndex % angleRotation.length]).trim()
      : "";

    const creativeDirection = postType === "Post"
      ? String(post.creative_direction || creativeDirections[dayIndex % creativeDirections.length]).trim()
      : "";

    const adFocus = postType === "Post"
      ? String(post.ad_focus || adFocuses[dayIndex % adFocuses.length]).trim()
      : "";

    const productFocus = postType === "Post"
      ? String(post.product_focus || "premium Aquafoundry product").trim()
      : "";

    const productType = postType === "Post"
      ? String(post.product_type || "").trim()
      : "";

    let renderingMode = postType === "Post"
      ? String(post.rendering_mode || "").trim()
      : "";

    if (!renderingMode && productType) {
      const type = productType.toLowerCase();
      if (["pesto", "dressing", "sauce", "jar", "bottle"].some(t => type.includes(t))) {
        renderingMode = "packaging_locked";
      } else {
        renderingMode = "creative_food_scene";
      }
    }

    if (!renderingMode) {
      renderingMode = "creative_food_scene";
    }

    const selectedProductReferenceId = postType === "Post"
      ? String(post.selected_product_reference_id || post.selected_product_reference?.id || "").trim()
      : "";

    const selectedProductReferenceUrl = postType === "Post"
      ? String(post.selected_product_reference_url || post.selected_product_reference?.url || "").trim()
      : "";

    const selectedProductLabelUrl = postType === "Post"
      ? String(post.selected_product_label_url || post.selected_product_reference?.label_url || "").trim()
      : "";

    const productLabelRule = postType === "Post"
      ? String(post.product_label_rule || post.selected_product_reference?.label_rule || "").trim()
      : "";

    const servingFormat = postType === "Post"
      ? String(post.serving_format || post.selected_product_reference?.serving_format || "").trim()
      : "";

    const forbiddenVisuals = postType === "Post"
      ? String(post.forbidden_visuals || post.selected_product_reference?.forbidden_visuals || "").trim()
      : "";

    const selectedDesignReferenceId = postType === "Post"
      ? String(post.selected_design_reference_id || post.selected_design_reference?.id || "").trim()
      : "";

    const designReferenceStyle = postType === "Post"
      ? String(
          post.design_reference_style ||
          post.selected_design_reference?.style ||
          post.selected_design_reference?.style_guidance ||
          ""
        ).trim()
      : "";

    const compositionDirection = postType === "Post"
      ? String(post.composition_direction || compositionDirections[dayIndex % compositionDirections.length]).trim()
      : "";

    const mascotAction = postType === "Post"
      ? String(post.mascot_action || mascotActions[dayIndex % mascotActions.length]).trim()
      : "";

    let imagePrompt = postType === "Post"
      ? String(post.ai_image_prompt || "premium Indian food/product advertising scene, natural daylight").trim()
      : "";

    if (postType === "Post" && adFocus.toLowerCase().includes("product")) {
      if (!imagePrompt.toLowerCase().includes("product hero composition")) {
        imagePrompt = `Product hero composition, ${imagePrompt}`;
      }
    }

    if (postType === "Post" && renderingMode === "packaging_locked") {
      if (!imagePrompt.toLowerCase().includes("blank label")) {
        imagePrompt += ", realistic blank label area on the product packaging for exact label compositing later";
      }

      if (!imagePrompt.toLowerCase().includes("no text")) {
        imagePrompt += ", no text, no logo, no mascot, no product label text";
      }
    }

    if (postType === "Post" && renderingMode === "creative_food_scene") {
      if (!imagePrompt.toLowerCase().includes("no text")) {
        imagePrompt += ", no text, no logo, no mascot";
      }
    }

    flattenedRows.push({
      Row_ID: rowId,
      Day: dayValue,
      Post_Number: `post-${index + 1}`,
      Post_Type: postType,

      Marketing_Angle: marketingAngle,
      Creative_Direction: creativeDirection,
      Ad_Focus: adFocus,
      Product_Focus: productFocus,

      Product_Type: productType,
      Rendering_Mode: renderingMode,
      Selected_Product_Label_URL: selectedProductLabelUrl,
      Product_Label_Rule: productLabelRule,
      Serving_Format: servingFormat,
      Forbidden_Visuals: forbiddenVisuals,
      Product_Visual_Identity: post.product_visual_identity || "",
      Product_Color_Direction: post.product_color_direction || "",
      Packaging_Photography_Style: post.packaging_photography_style || "",
      Product_Priority_Type: post.product_priority_type || "",

      Selected_Product_Reference_ID: selectedProductReferenceId,
      Selected_Product_Reference_URL: selectedProductReferenceUrl,

      Selected_Design_Reference_ID: selectedDesignReferenceId,
      Design_Reference_Style: designReferenceStyle,

      Composition_Direction: compositionDirection,
      Mascot_Action: mascotAction,

      Image_Prompt: imagePrompt,

      Video_Script_Prompt: postType === "Reel"
        ? String(post.video_script_prompt || "").trim()
        : "",

      Headline: headline,
      CTA: cta,
      Features: postType === "Post" ? features.join(" | ") : "",

      Caption: String(post.caption || "Fresh sustainable farming. #aquaponics").trim(),

      Selected_Logo_URL: "",
      Selected_Mascot_URL: "",
      Creative_Strategy: "",
      Product_Usage_Direction: "",
      Design_Usage_Direction: "",
      Mascot_Scene_Direction: "",

      Status: "pending",
      Image_URL: ""
    });
  });
});

return flattenedRows;

