};

const original = $item(0).$node["Preserve Raw Image"].json;
const rawBinary = $item(0).$node["Preserve Raw Image"].binary.raw_image;

let raw =
  $json.candidates?.[0]?.content?.parts?.[0]?.text ||
  $json.content?.parts?.[0]?.text ||
  $json.text ||
  "";

if (!raw) {
  throw new Error("No text found in Analyze response:\n" + JSON.stringify($json, null, 2));
}

raw = String(raw)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const jsonMatch = raw.match(/\{[\s\S]*\}/);

if (!jsonMatch) {
  throw new Error("No JSON object found:\n" + raw);
}

let parsed;

try {
  parsed = JSON.parse(jsonMatch[0]);
} catch (error) {
  throw new Error("Invalid asset decision JSON:\n" + raw);
}

if (!parsed.selected_logo_url || !parsed.selected_mascot_url) {
  throw new Error("Asset decision missing selected logo or mascot:\n" + raw);
}

return {
  json: {
    ...original,

    Selected_Logo_URL: String(parsed.selected_logo_url || "").trim(),
    Selected_Mascot_URL: String(parsed.selected_mascot_url || "").trim(),

    Creative_Strategy: parsed.creative_strategy || "",
    Product_Usage_Direction: parsed.product_usage_direction || "",
    Design_Usage_Direction: parsed.design_usage_direction || "",
    Mascot_Scene_Direction: parsed.mascot_scene_direction || ""
  },
  binary: {
    raw_image: rawBinary
  }
};

const original = $item(0).$node["Parse Asset Decision"].json;
const previousBinary = $item(0).$node["Parse Asset Decision"].binary;

return {
  json: {
    ...original
  },
  binary: {
    ...previousBinary,
    ...$binary
  }
};

